using System;using System.IO;using System.Text.Json;using System.Collections.Generic;using System.Reflection;using System.Globalization;using Exoduser.UnityPort.Core;
class Program {
 static readonly List<object> Rows=new List<object>();static int failures;static Type Hud;
 static void Check(bool ok,string name){Rows.Add(new{name,passed=ok});if(!ok)failures++;}
 static int Finish(string output){File.WriteAllText(output,JsonSerializer.Serialize(new{scope="standalone_dotnet_original_DOM_oracle_not_Unity_runtime",passed=failures==0,failed=failures,checks=Rows},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("HUD_RESULT "+Rows.Count+" checks / "+failures+" failures");return failures==0?0:2;}
 static object Value(object h,string key)=>Hud.GetProperty(key).GetValue(h);
 static double Number(object h,string key)=>Convert.ToDouble(Value(h,key),CultureInfo.InvariantCulture);
 static bool Near(double a,double b)=>Math.Abs(a-b)<.0001;
 static double Percent(string text)=>double.Parse(text.Substring(text.IndexOf('(')+1).TrimEnd(')', '%'),CultureInfo.InvariantCulture);
 static object Read(PlayerState p)=>Hud.GetMethod("From").Invoke(null,new object[]{p});
 static int Main(string[] args){Hud=typeof(PlayerState).Assembly.GetType("Exoduser.UnityPort.Core.HudValues");Check(Hud!=null,"source-backed native HUD value adapter exists");if(Hud==null)return Finish(args[0]);
 using(var oracle=JsonDocument.Parse(File.ReadAllText(args[1])))foreach(var row in oracle.RootElement.GetProperty("rows").EnumerateArray()){
 var i=row.GetProperty("input");var e=row.GetProperty("expected");var p=new PlayerState{Hp=i.GetProperty("hp").GetSingle(),MaxHp=i.GetProperty("mhp").GetSingle(),Mana=i.GetProperty("mp").GetSingle(),MaxMana=i.GetProperty("mmp").GetSingle(),Stamina=i.GetProperty("st").GetSingle(),MaxStamina=i.GetProperty("mst").GetSingle(),Shield=i.GetProperty("shield").GetSingle(),MaxShield=i.GetProperty("mshield").GetSingle(),Poise=i.GetProperty("poise").GetSingle(),State=i.GetProperty("s").GetString(),Experience=i.GetProperty("exp").GetInt32(),MaxExperience=i.GetProperty("maxExp").GetInt32()};var before=JsonSerializer.Serialize(p,new JsonSerializerOptions{IncludeFields=true});var h=Read(p);string n=row.GetProperty("name").GetString();
 Check(Near(Number(h,"HpTranslatePercent"),Percent(e.GetProperty("hpTransform").GetString())),n+" original HP visible-window mapping");Check(Near(Number(h,"ManaTranslatePercent"),Percent(e.GetProperty("mpTransform").GetString()))&&Near(Number(h,"StaminaTranslatePercent"),Percent(e.GetProperty("stTransform").GetString())),n+" independent original MP/ST fills");
 Check(Near(Number(h,"ManaRatio"),1-Percent(e.GetProperty("mpTransform").GetString())/100)&&Near(Number(h,"StaminaRatio"),1-Percent(e.GetProperty("stTransform").GetString())/100)&&Math.Abs(Number(h,"HpRatio")-(1-(Percent(e.GetProperty("hpTransform").GetString())-10)/87))<.00006,n+" ratios agree with original DOM transforms");
 bool texts=true;foreach(var pair in new[]{new[]{"HpCurrentText","hpCurrent"},new[]{"HpMaximumText","hpMaximum"},new[]{"ManaCurrentText","mpCurrent"},new[]{"ManaMaximumText","mpMaximum"},new[]{"StaminaCurrentText","stCurrent"},new[]{"StaminaMaximumText","stMaximum"},new[]{"ExperienceText","experienceText"}})texts&=(string)Value(h,pair[0])==e.GetProperty(pair[1]).GetString();Check(texts,n+" original integer text and XP grouping");
 Check(Near(Number(h,"ExperienceRatio"),double.Parse(e.GetProperty("experienceWidth").GetString().TrimEnd('%'),CultureInfo.InvariantCulture)/100),n+" source XP ratio without fabricated cap");
 var eyes=(bool[])Value(h,"PoiseEyes");bool eyesMatch=eyes.Length==4;int k=0;foreach(var eye in e.GetProperty("poiseEyes").EnumerateArray())eyesMatch&=eyes[k++]==eye.GetBoolean();Check(eyesMatch,n+" original fractional poise eyes and stun");
 string ring=e.GetProperty("shieldBackground").GetString();if(ring=="none")Check(Number(h,"ShieldRatio")==0,n+" no shield ring");else{var m=System.Text.RegularExpressions.Regex.Match(ring,@"255,([\d.]+)\) ([\d.]+)%");Check(m.Success&&Near(Number(h,"ShieldRatio"),double.Parse(m.Groups[2].Value,CultureInfo.InvariantCulture)/100)&&Near(Math.Round(Number(h,"ShieldAlpha")*.9,2,MidpointRounding.AwayFromZero),double.Parse(m.Groups[1].Value,CultureInfo.InvariantCulture)),n+" original shield ratio and raw alpha");}
 Check(before==JsonSerializer.Serialize(p,new JsonSerializerOptions{IncludeFields=true}),n+" rendering adapter never mutates player");}
 foreach(float invalid in new[]{0f,-1f,float.NaN,float.PositiveInfinity}){var p=new PlayerState{Hp=2,MaxHp=invalid,Mana=2,MaxMana=invalid,Stamina=2,MaxStamina=invalid,MaxExperience=0};var h=Read(p);Check(!(bool)Value(h,"HpValid")&&!(bool)Value(h,"ManaValid")&&!(bool)Value(h,"StaminaValid")&&!(bool)Value(h,"ExperienceValid")&&Number(h,"HpRatio")==0&&Number(h,"ManaRatio")==0&&Number(h,"StaminaRatio")==0&&(string)Value(h,"HpCurrentText")==""&&(string)Value(h,"ManaCurrentText")==""&&(string)Value(h,"StaminaCurrentText")==""&&(string)Value(h,"HpMaximumText")==""&&(string)Value(h,"ManaMaximumText")==""&&(string)Value(h,"StaminaMaximumText")==""&&(string)Value(h,"ExperienceText")=="","invalid maximum guard "+invalid);}
 foreach(float invalid in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity}){var h=Read(new PlayerState{Hp=invalid,MaxHp=100,Mana=invalid,MaxMana=100,Stamina=invalid,MaxStamina=100,Shield=invalid,MaxShield=100});Check(!(bool)Value(h,"HpValid")&&!(bool)Value(h,"ManaValid")&&!(bool)Value(h,"StaminaValid")&&Number(h,"ShieldRatio")==0&&Number(h,"ShieldAlpha")==0,"nonfinite resource guard "+invalid);}
 var zero=Read(new PlayerState{Shield=50,MaxShield=0});Check(Number(zero,"ShieldRatio")==0&&Number(zero,"ShieldAlpha")==0,"zero shield maximum is absent ring without fabricated shield");
 var tiny=Read(new PlayerState{Hp=1,MaxHp=.5f,Mana=1,MaxMana=.5f});Check(!(bool)Value(tiny,"HpValid")&&!(bool)Value(tiny,"ManaValid"),"HP/MP maxima truncated to zero are guarded");
 return Finish(args[0]);}
}
